alm-数据模型图1. 核心实体关系图erDiagram DEVICE &#123; string id PK string name string ip string mac string type string model string os_version date purchase_date string warranty_info string owner string[] teams boolean is_online &#125;
TEST_CASE &#123; string id PK string name string description string purpose string precondition string[] steps string expected_result string[] tags string creator string maintainer string priority string importance boolean is_automated string script_path string[] applicable_versions &#125;
REQUIREMENT &#123; string id PK string name string description string type string priority string status string version string complexity string[] acceptance_criteria string owner string[] teams date created_date date due_date &#125;
PROJECT &#123; string id PK string name string description string[] members string[] roles date start_date date end_date string status string progress &#125;
DEFECT &#123; string id PK string title string description string severity string priority string type string[] reproduction_steps string expected_result string actual_result string environment_info string hardware_version string software_version string discovery_phase string root_cause string status string assignee date due_date string resolution &#125;
TEST_EXECUTION &#123; string id PK string test_case_id FK string project_id FK string device_id FK string executor date execution_date string status string result string failure_reason int duration string[] attachments string environment &#125;
TEST_PLAN &#123; string id PK string name string description string project_id FK string[] test_case_ids string environment date planned_start date planned_end string status string creator &#125;
TEST_RESULT &#123; string id PK string test_execution_id FK string status string details string[] logs string[] screenshots string[] videos string environment_details &#125;
USER &#123; string id PK string username string email string full_name string[] roles string[] teams boolean active &#125;
DEVICE_LOG &#123; string id PK string device_id FK date timestamp string level string message string source string context &#125;
DEVICE ||--o&#123; DEVICE_LOG : &quot;generates&quot; DEVICE ||--o&#123; TEST_EXECUTION : &quot;used in&quot;
TEST_CASE ||--o&#123; TEST_EXECUTION : &quot;executed as&quot; TEST_CASE &#125;o--o&#123; REQUIREMENT : &quot;covers&quot;
TEST_EXECUTION ||--|| TEST_RESULT : &quot;produces&quot; TEST_EXECUTION &#125;o--o&#123; DEFECT : &quot;identifies&quot;
PROJECT ||--o&#123; TEST_PLAN : &quot;contains&quot; PROJECT ||--o&#123; REQUIREMENT : &quot;implements&quot;
TEST_PLAN ||--o&#123; TEST_EXECUTION : &quot;schedules&quot;
REQUIREMENT &#125;o--o&#123; DEFECT : &quot;affected by&quot;
USER ||--o&#123; TEST_EXECUTION : &quot;executes&quot; USER ||--o&#123; TEST_CASE : &quot;creates&quot; USER ||--o&#123; DEFECT : &quot;reports&quot; USER ||--o&#123; PROJECT : &quot;participates in&quot;
